CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, username text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read_own ON public.profiles FOR SELECT TO authenticated USING (auth.uid() = id);
CREATE POLICY profiles_update_own ON public.profiles FOR UPDATE TO authenticated USING (auth.uid() = id) WITH CHECK (auth.uid() = id);
CREATE TABLE public.game_saves (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, state jsonb NOT NULL DEFAULT '{}'::jsonb, version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.game_saves TO authenticated;
GRANT ALL ON public.game_saves TO service_role;
ALTER TABLE public.game_saves ENABLE ROW LEVEL SECURITY;
CREATE POLICY saves_read_own ON public.game_saves FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE TABLE public.game_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, state jsonb NOT NULL, sequence integer NOT NULL DEFAULT 0, started_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), finished boolean NOT NULL DEFAULT false, rewarded boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.game_runs TO authenticated;
GRANT ALL ON public.game_runs TO service_role;
ALTER TABLE public.game_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY runs_read_own ON public.game_runs FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE UNIQUE INDEX one_active_run_per_user ON public.game_runs (user_id) WHERE finished = false;
CREATE FUNCTION public.create_player_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, username) VALUES(NEW.id, COALESCE(NULLIF(NEW.raw_user_meta_data->>'username',''), 'Survivor')); RETURN NEW; END; $$;
CREATE TRIGGER hollowfall_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_player_profile();
CREATE FUNCTION public.commit_game_save(p_user uuid, p_version integer, p_state jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE affected integer; BEGIN UPDATE public.game_saves SET state=p_state, version=p_version+1, updated_at=now() WHERE user_id=p_user AND version=p_version; GET DIAGNOSTICS affected = ROW_COUNT; RETURN affected=1; END; $$;
REVOKE ALL ON FUNCTION public.commit_game_save(uuid,integer,jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.commit_game_save(uuid,integer,jsonb) TO service_role;
CREATE FUNCTION public.commit_game_run(p_user uuid, p_run uuid, p_sequence integer, p_state jsonb, p_finished boolean, p_save jsonb, p_save_version integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE r public.game_runs; BEGIN SELECT * INTO r FROM public.game_runs WHERE id=p_run AND user_id=p_user FOR UPDATE; IF NOT FOUND OR r.sequence<>p_sequence OR r.rewarded THEN RETURN false; END IF; IF p_save IS NOT NULL THEN UPDATE public.game_saves SET state=p_save,version=p_save_version+1,updated_at=now() WHERE user_id=p_user AND version=p_save_version; IF NOT FOUND THEN RETURN false; END IF; END IF; UPDATE public.game_runs SET state=p_state,sequence=p_sequence+1,finished=p_finished,rewarded=(p_save IS NOT NULL),updated_at=now() WHERE id=p_run; RETURN true; END; $$;
REVOKE ALL ON FUNCTION public.commit_game_run(uuid,uuid,integer,jsonb,boolean,jsonb,integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.commit_game_run(uuid,uuid,integer,jsonb,boolean,jsonb,integer) TO service_role;